Box PlayerActor::GetBox() const
{
    if (IsRidingHorse())
    {
        Box bounds(-7, -9, 7, 5, x_q16 >> 16, y_q16 >> 16);
        return bounds;
    }
    else
    {
        Box bounds = AActorEntity::GetBox();
        return bounds;
    }
}

