void PlayerActor::EnterHotSpringBathingState()
{
    action_state = 8;
    unk_3D = 0xFF;
}

void PlayerActor::ExitHotSpringBathingState()
{
    action_state = 0;
}

bool PlayerActor::IsClockPausedByAction()
{
    if (!IsNormalUpdateSuspended())
        return IsActionInRange(action_state, 0x24, 0x2A);
    return false;
}

