void UpdatePlayerPedometer(PlayerActor const & player)
{
    u32 previous = player.farmer->GetStepCount();
    player.farmer->RecordPedometerStep();
    if (previous != player.farmer->GetStepCount()) {
        switch (player.farmer->GetStepCount()) {
        case 10000:
            player.game_object->QueueScript(GameSceneScriptRequest(
                EventScript_0822_AchievementEvent_Pedometer_10000Steps, 0), 1);
            break;
        case 100000:
            player.game_object->QueueScript(GameSceneScriptRequest(
                EventScript_0823_AchievementEvent_Pedometer_100000Steps, 0), 1);
            break;
        case 1000000:
            player.game_object->QueueScript(GameSceneScriptRequest(
                EventScript_0824_AchievementEvent_Pedometer_1000000Steps, 0), 1);
            break;
        case 10000000:
            player.game_object->QueueScript(GameSceneScriptRequest(
                EventScript_0825_AchievementEvent_Pedometer_10000000Steps, 0), 1);
            break;
        case 100000000:
            player.game_object->QueueScript(GameSceneScriptRequest(
                EventScript_0826_AchievementEvent_Pedometer_100000000Steps, 0), 1);
            break;
        case 1000000000:
            player.game_object->QueueScript(GameSceneScriptRequest(
                EventScript_0827_AchievementEvent_Pedometer_1000000000Steps, 0), 1);
            break;
        }
    }
}

static inline FieldRenderTileAttributes const * GetTerrainTile(
    MapTerrainView const & terrain, u32 x, u32 y)
{
    FieldRenderTileAttributes const * attributes = terrain.attributes;
    u32 width = terrain.width;
    if (attributes != nullptr && x <= width && y <= terrain.height) {
        u8 const * indices = terrain.indices;
        u32 index = y * width + x;
        if (indices != nullptr)
            return attributes + indices[index];
        return attributes + index;
    }
    return nullptr;
}

bool IsActorTerrainBlocked(AActorEntity const & actor)
{
    GameObject * world = actor.game_object;
    u32 map = actor.location_map;
    MapTerrainView const & terrain = world->GetMapTerrain(map);
    Box box_value = UnkMapBox(actor.GetBox());
    Box & box = box_value;
    if (IsMapTerrainBoxBlocked(terrain, box))
        return true;
    // Mine collision checks the two terrain attribute fields; their individual roles remain unknown.
    if (map >= MAP_SPRING_MINE_FLOOR_0 && map <= MAP_LAKE_MINE_FLOOR_255) {
        FieldRenderTileAttributes const * tile = GetTerrainTile(terrain, box.x1 / 8, box.y1 / 8);
        if (tile != nullptr && (tile->unk_00_02 != 0 || (u32)tile->unk_02_00 != 0))
            return true;
        tile = GetTerrainTile(terrain, box.x1 / 8, (box.y2 - 1) / 8);
        if (tile != nullptr && (tile->unk_00_02 != 0 || (u32)tile->unk_02_00 != 0))
            return true;
        tile = GetTerrainTile(terrain, (box.x2 - 1) / 8, box.y1 / 8);
        if (tile != nullptr && (tile->unk_00_02 != 0 || (u32)tile->unk_02_00 != 0))
            return true;
        tile = GetTerrainTile(terrain, (box.x2 - 1) / 8, (box.y2 - 1) / 8);
        if (tile != nullptr && (tile->unk_00_02 != 0 || (u32)tile->unk_02_00 != 0))
            return true;
    }
    return false;
}

void CheckPlayerCollectionEvents(PlayerActor const & player)
{
    if (player.save_image->mine_floor.CountHarvestGoddessJewels() == 9
        && player.save_image->event_state.harvest_goddess_jewel_exchange_state == EVENT_LIFECYCLE_NOT_STARTED
        && player.farmer->held_item.GetKind() == HeldItem::KIND_ARTICLE
        && player.farmer->held_item.GetArticle().GetId() == ITEM_ARTICLE_HARVEST_GODDESS_JEWEL) {
        player.game_object->QueueScript(GameSceneScriptRequest(
            EventScript_0816_AchievementEvent_Collection_HarvestGoddessJewelsExchange, 0), 0);
    }
    if (player.save_image->mine_floor.CountKappaJewels() == 9
        && player.save_image->event_state.kappa_jewel_exchange_state == EVENT_LIFECYCLE_NOT_STARTED
        && player.farmer->held_item.GetKind() == HeldItem::KIND_ARTICLE
        && player.farmer->held_item.GetArticle().GetId() == ITEM_ARTICLE_KAPPA_JEWEL) {
        player.game_object->QueueScript(GameSceneScriptRequest(
            EventScript_0818_AchievementEvent_Collection_KappaJewelsExchange, 0), 0);
    }
    if (player.save_image->event_state.achievement_collected_every_spring_mine_item_state == ACHIEVEMENT_EVENT_NOT_REACHED) {
        bool all_shipped = true;
        for (u32 i = 0; i < ARRAY_COUNT(gSpringMineCollectionProducts); ++i) {
            if (!player.save_image->farm.shipping_bin.IsDisplayEnabled(gSpringMineCollectionProducts[i])) {
                all_shipped = false;
                break;
            }
        }
        if (all_shipped
            && player.save_image->mine_floor.HasFoundSpringMinePowerBerry()
            && player.save_image->mine_floor.HasFoundLithograph()
            && player.save_image->mine_floor.CountHarvestGoddessJewels()
            && player.save_image->mine_floor.HasFoundTeleportStone()) {
            player.game_object->QueueScript(GameSceneScriptRequest(
                EventScript_0845_AchievementEvent_SpringMine_CollectedEveryItem, 0), 0);
        }
    }
    if (player.save_image->event_state.achievement_collected_every_lake_mine_item_state == ACHIEVEMENT_EVENT_NOT_REACHED) {
        bool all_shipped = true;
        for (u32 i = 0; i < ARRAY_COUNT(gLakeMineCollectionProducts); ++i) {
            if (!player.save_image->farm.shipping_bin.IsDisplayEnabled(gLakeMineCollectionProducts[i])) {
                all_shipped = false;
                break;
            }
        }
        if (all_shipped
            && player.save_image->cursed_tools.HaveFoundAllTools()
            && player.save_image->mine_floor.HasFoundLakeMinePowerBerry()
            && player.save_image->mine_floor.CountKappaJewels()) {
            player.game_object->QueueScript(GameSceneScriptRequest(
                EventScript_0846_AchievementEvent_LakeMine_CollectedEveryItem, 0), 0);
        }
    }
}

PlayerSpriteController::PlayerSpriteController(PlayerActor * player)
    : EntitySpriteController(player, 6, gPlayerSpritePaletteKinds, 3,
          ENTITY_AUX_RENDER_DEFAULT, 0, 1, true),
      held_actor_sprite(player->game_object->vfunc_64(), 0, player->GetGameObject(), 2, 1, false),
      slots(), unk_281(0)
{
    for (u32 i = 0; i < PlayerSpriteSlots::CAPACITY; ++i)
        slots.Push(PlayerSpriteSlot(player->game_object->vfunc_68(), player->GetGameObject()));
    next_slot = 0;
}

void PlayerSpriteController::Update()
{
    EntitySpriteController::Update();
    PlayerActor * player = static_cast<PlayerActor *>(entity);
    u8 frame_changed = GetFrameChangeFlag();
    if (player->unk_7C != 0xFFFF && frame_changed == 0)
        player->unk_7C = 0xFFFF;
    if (player->IsHoldingActorGraphic())
        held_actor_sprite.UpdateAnimation();
    for (u32 i = 0; i < PlayerSpriteSlots::CAPACITY; ++i)
        slots[i].Update();
}

