PlayerActorBase::PlayerActorBase(GameObject * world, GameStateSaveImage * save)
    : AActorEntity(world, save->farmer.GetLocation(), 2, 0x192)
{
}

FarmingTutorialPlayerBase::FarmingTutorialPlayerBase(GameObject * world)
    : AActorEntity(world, ActorLocation(Location(MAP_NONE, 0, 0), FACING_DOWN), 2, 0)
{
}

FarmingTutorialPlayer::FarmingTutorialPlayer(GameObject * world)
    : FarmingTutorialPlayerBase(world), action(0), show_tool_countdown(0),
      graphic(), action_active(false), held_graphic_id(0),
      skip_action_update(false), holding_item(false)
{
    AEntity::vfunc_10();
}

EntityVisualController * FarmingTutorialPlayer::CreateVisualController()
{
    return new FarmingTutorialPlayerSpriteController(this);
}

asm_unified(
    ".text\n"
);

void FarmingTutorialPlayer::UpdateWhileSuspended(
    EntityUpdateContext const & context)
{
    if (!skip_action_update)
    {
        if (action_active)
        {
            UpdateAction();

            u16 animation = (u16)GetActionAnimation();

            if (anim_id != animation)
                SetAnim(animation);
        }
    }
    else
    {
        skip_action_update = false;
    }

    AActorEntity::UpdateWhileSuspended(context);
}

