u32 FarmingTutorialPlayer::GetActionAnimation() const
{
    u32 animation = 0x192;

    switch (action)
    {
    case 0:
        animation = !holding_item ? (0x152 + 0x40) : 0x152;
        break;
    case 1:
    case 2:
        animation = 0x19E;
        break;
    case 3:
        animation = 0x146;
        break;
    case 4:
        animation = 0x42;
        break;
    }

    return animation;
}

